// --- Clinic time formatting (presentation layer only; DB stores HH:mm) ---
const CLINIC_TIMEZONE = 'Asia/Karachi';

function parseClinicTime(raw) {
  if (raw == null || raw === '') return null;
  const s = String(raw).trim().replace(/\s+/g, ' ');
  const zone = CLINIC_TIMEZONE;
  const formats = ['HH:mm', 'H:mm', 'HH:mm:ss', 'H:mm:ss', 'h:mm a', 'h:mma', 'hh:mm a', 'hh:mma', 'h a', 'ha', 'h:mm:ss a'];
  for (const fmt of formats) {
    const dt = DateTime.fromFormat(s, fmt, { zone, locale: 'en' });
    if (dt.isValid) return dt;
  }
  const iso = DateTime.fromISO(s, { zone });
  if (iso.isValid && /T|\d:\d/.test(s)) return iso;
  return null;
}

function toStoredTime(raw) {
  const dt = parseClinicTime(raw);
  return dt ? dt.toFormat('HH:mm') : null;
}

function formatTime12h(raw) {
  const dt = parseClinicTime(raw);
  if (!dt) return raw;
  return dt.setLocale('en-US').toFormat('h:mm a').replace(/\b(am|pm)\b/gi, (m) => m.toUpperCase());
}

function clinicNow() {
  return DateTime.now().setZone(CLINIC_TIMEZONE);
}

function formatDateDisplay(isoOrDate) {
  const raw = String(isoOrDate || '').trim();
  const datePart = raw.includes('T') ? raw.split('T')[0] : raw.slice(0, 10);
  const dt = DateTime.fromISO(datePart, { zone: CLINIC_TIMEZONE });
  return dt.isValid ? dt.toFormat('MMMM d, yyyy') : raw;
}
// --- end clinic time formatting ---

const CANCELLATION_CUTOFF_MINUTES = 15;


function rowsFrom(nodeName) {
  const items = $(nodeName).all();
  const out = [];
  for (const item of items) {
    const j = item.json;
    if (Array.isArray(j)) {
      for (const row of j) out.push(row);
    } else if (j && typeof j === 'object') {
      // empty object / error body without id fields
      if (j.doctor_id || j.appointment_id || j.clinic_id) out.push(j);
      else if (Array.isArray(j.body)) {
        for (const row of j.body) out.push(row);
      }
    }
  }
  return out;
}

const items = rowsFrom('Get Appointment');
const appt = items[0] || null;

if (!appt || !appt.appointment_id) {
  return [{ json: { canCancel: false, message: 'No appointment found with that ID. Please double-check and try again.' } }];
}
if (appt.status === 'cancelled') {
  return [{ json: { canCancel: false, message: 'This appointment has already been cancelled.' } }];
}

const datePart = String(appt.appointment_date || '').includes('T') ? DateTime.fromISO(appt.appointment_date, { zone: CLINIC_TIMEZONE }).toFormat('yyyy-MM-dd') : String(appt.appointment_date || '').slice(0, 10);
const storedTime = toStoredTime(appt.appointment_time);
const apptDateTime = DateTime.fromFormat(datePart + ' ' + storedTime, 'yyyy-MM-dd HH:mm', { zone: CLINIC_TIMEZONE });
if (apptDateTime.isValid) {
  const now = clinicNow();
  const minutesUntil = apptDateTime.diff(now, 'minutes').minutes;

  if (minutesUntil <= 0) {
    return [{ json: { canCancel: false, message: 'This appointment time has already passed, so it cannot be cancelled.' } }];
  }
  if (minutesUntil <= CANCELLATION_CUTOFF_MINUTES) {
    return [{ json: { canCancel: false, message: 'Sorry, this appointment cannot be cancelled because it is too close to the scheduled time. Cancellation is only allowed up to ' + CANCELLATION_CUTOFF_MINUTES + ' minutes before the appointment.' } }];
  }
}

return [{ json: {
  canCancel: true,
  appointment_id: appt.appointment_id,
  doctor_name: appt.doctor_name,
  appointment_date: appt.appointment_date,
  appointment_time: storedTime || appt.appointment_time,
  appointment_date_display: formatDateDisplay(appt.appointment_date),
  appointment_time_display: formatTime12h(appt.appointment_time),
  timezone: CLINIC_TIMEZONE
} }];

